import{_ as e,o as s,c as i,a2 as l}from"./chunks/framework.LX5S0jbT.js";const g=JSON.parse('{"title":"使用 llama.cpp 运行本地模型","description":"","frontmatter":{},"headers":[],"relativePath":"zh/llama-cpp.md","filePath":"zh/llama-cpp.md"}'),o={name:"zh/llama-cpp.md"};function n(p,a,t,c,d,h){return s(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="使用-llama-cpp-运行本地模型" tabindex="-1">使用 llama.cpp 运行本地模型 <a class="header-anchor" href="#使用-llama-cpp-运行本地模型" aria-label="Permalink to &quot;使用 llama.cpp 运行本地模型&quot;">​</a></h1><p>Pi 支持 <a href="https://github.com/ggml-org/llama.cpp" target="_blank" rel="noreferrer">llama.cpp</a> 的路由服务器（router）。路由器会发现多个 GGUF 模型并按需加载或卸载。</p><p>请使用支持 router 的较新 llama.cpp 构建。参考<a href="https://github.com/ggml-org/llama.cpp/blob/master/docs/build.md" target="_blank" rel="noreferrer">构建说明</a>，或为你的平台安装<a href="https://github.com/ggml-org/llama.cpp/releases" target="_blank" rel="noreferrer">预构建版本</a>。</p><h2 id="启动路由器" tabindex="-1">启动路由器 <a class="header-anchor" href="#启动路由器" aria-label="Permalink to &quot;启动路由器&quot;">​</a></h2><p>启动 <code>llama-server</code> 时不带 <code>--model</code> 或 <code>-m</code>。传入模型会进入单模型模式而不是路由器模式。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">llama-server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --models-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/models</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --no-models-autoload</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --jinja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -ngl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 999</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32768</span></span></code></pre></div><p>重要选项：</p><ul><li><code>--models-dir ~/models</code> 发现本地 GGUF 文件。</li><li><code>--no-models-autoload</code> 保持通过 <code>/llama</code> 显式加载。</li><li><code>--jinja</code> 启用兼容的聊天模板和工具调用。</li><li><code>-ngl 999</code> 尽可能多地把层卸载到 GPU。</li><li><code>-c 32768</code> 为每个已加载模型设置上下文窗口。省略则使用模型原生上下文，但可能需要显著更多内存。</li></ul><p>单文件模型可以直接放在模型目录中。多模态模型和多分片（multi-shard）模型放在单独的子目录中：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/models/</span></span>
<span class="line"><span>├── llama-3.2-1b-Q4_K_M.gguf</span></span>
<span class="line"><span>├── gemma-3-4b-it-Q4_K_M/</span></span>
<span class="line"><span>│   ├── gemma-3-4b-it-Q4_K_M.gguf</span></span>
<span class="line"><span>│   └── mmproj-F16.gguf</span></span>
<span class="line"><span>└── large-model-Q4_K_M/</span></span>
<span class="line"><span>    ├── large-model-Q4_K_M-00001-of-00003.gguf</span></span>
<span class="line"><span>    ├── large-model-Q4_K_M-00002-of-00003.gguf</span></span>
<span class="line"><span>    └── large-model-Q4_K_M-00003-of-00003.gguf</span></span></code></pre></div><p>手动添加文件后重启路由器。要为每个模型设置上下文大小等选项，使用 <a href="https://github.com/ggml-org/llama.cpp/blob/master/tools/server/README.md#model-presets" target="_blank" rel="noreferrer">llama.cpp model presets</a>。针对特定 NVIDIA GPU 和模型的设置，参见 <a href="./nvidia-rtx-llama-cpp.html">Run Pi with NVIDIA RTX and llama.cpp</a>。</p><p><a id="configure-pi"></a></p><h2 id="配置-pi" tabindex="-1">配置 Pi <a class="header-anchor" href="#配置-pi" aria-label="Permalink to &quot;配置 Pi&quot;">​</a></h2><p>启动 Pi 并配置提供商（provider）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/login llama.cpp</span></span></code></pre></div><p>输入路由器 URL 和可选的 API key。默认 URL 为 <code>http://127.0.0.1:8080</code>。</p><p>如果用 <code>--no-models-autoload</code> 启动路由器，<code>/login llama.cpp</code> 只保存连接信息。运行 <code>/llama</code> 加载模型，然后用 <code>/model</code> 为当前会话选择已加载的模型。</p><p>也可以通过环境变量配置这些值，无需 <code>/login</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLAMA_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLAMA_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">optional-secret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span></span></code></pre></div><p>如果服务器使用 API key，启动 <code>llama-server</code> 时使用匹配的 <code>--api-key</code>。保留 <code>--host 127.0.0.1</code> 以仅限本地访问。</p><h2 id="管理模型" tabindex="-1">管理模型 <a class="header-anchor" href="#管理模型" aria-label="Permalink to &quot;管理模型&quot;">​</a></h2><p>运行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/llama</span></span></code></pre></div><ul><li>选择未加载的模型来加载它。</li><li>选择已加载的模型来卸载它。</li><li>选择 <strong>Download model…</strong>，搜索 Hugging Face，然后选择仓库和量化（quantization）。也支持精确的 <code>owner/repository[:quant]</code> 值。</li><li>在加载或下载过程中按 Escape 确认取消。</li></ul><p>Hugging Face 搜索在设置了 <code>HF_TOKEN</code> 时使用它，随后依次检查 <code>$HF_TOKEN_PATH</code>、<code>$HF_HOME/token</code>、<code>$XDG_CACHE_HOME/huggingface/token</code> 和 <code>~/.cache/huggingface/token</code>。无认证也可以搜索，但速率限制更低。下载受限（gated）仓库前 Pi 会警告并提供其访问页面链接。下载由 llama.cpp 服务器执行，因此当所选仓库需要访问权限时，其进程也必须有 <code>HF_TOKEN</code>。</p><p>如果已加载其他模型，Pi 会询问是先卸载它们还是保持加载。Pi 不会静默卸载模型，也从不删除模型文件。路由器可能与其他客户端共享，因此 <code>/llama</code> 总是显示路由器的当前状态。</p><p>已加载和休眠（sleeping）的模型会出现在 <code>/model</code> 中。休眠模型在被选中时自动唤醒。启用 router 自动加载时，未加载的预设（preset）模型也会出现并在被选中时加载。使用 <code>--no-models-autoload</code> 时，先通过 <code>/llama</code> 加载模型再选择。</p><p>如果路由器断开连接，<code>/llama</code> 显示 <strong>Retry</strong> 和 <strong>Close</strong>。Retry 重新连接并刷新模型状态，不重放被中断的操作。</p><p><a id="classification"></a></p><h2 id="分类模型" tabindex="-1">分类模型 <a class="header-anchor" href="#分类模型" aria-label="Permalink to &quot;分类模型&quot;">​</a></h2><p>分类器（classifier）模型回答关于 JSON 状态的输入式 <code>choice</code>、<code>bool</code> 和 <code>score</code> 问题，例如 TypeSafe 的 Jev 模型。模型从 <a href="./cli.html#enable-codemode"><code>codemode</code></a> 脚本访问它们，扩展则通过 <code>ctx.modelRegistry.classify()</code>；参见<a href="./models.html#use-classifier-models">分类器模型</a>。Pi 以两种方式将 llama.cpp 模型列为分类器：</p><ul><li><strong>决策模型（decision models）</strong>，如 <a href="https://huggingface.co/collections/ggml-org/decision-models-6abf80cca3c83f127060a769" target="_blank" rel="noreferrer">Julia-1、Laya、Kev、lev 和 OpenJev</a>，通过 llama.cpp 的 <code>/v1/systemone</code> 端点原生回答。它们只作为分类器出现，使用 <code>typesafe-system-one</code> API，且不出现在 <code>/model</code> 中。</li><li><strong>聊天模型（chat models）</strong> 也会以相同 ID 和 <code>llama-cpp-classify</code> API 列为分类器，该 API 如下文所述从 next-token 概率读取答案。</li></ul><p>llama.cpp 0.6.0 及更高版本会在路由器的模型列表中报告决策模型：其 <code>architecture.output_modalities</code> 包含 <code>decisions</code>。路由器从 GGUF 元数据中读取这一点，无需加载模型，因此 Pi 也能识别未加载和休眠的决策模型。较旧的 llama.cpp 构建不报告它，Pi 会将其决策模型列为聊天模型。</p><h3 id="以聊天模型作为分类器" tabindex="-1">以聊天模型作为分类器 <a class="header-anchor" href="#以聊天模型作为分类器" aria-label="Permalink to &quot;以聊天模型作为分类器&quot;">​</a></h3><p>模型不会生成答案。每个问题成为一条聊天提示词：状态、请求中的每个问题、再次出现的状态，然后是问题及其在单 token 标签（label）下的答案。标签对于 choice 是字母（最多 62 个选项），对于 bool 是 <code>Yes</code>/<code>No</code>，对于 score 是数字（最多 10 级）。状态以问题可见的方式被第二次读取，这在小模型的 JevBench 上提升了准确率。Pi 读取标签作为 next token 的概率并归一化。choice 返回每个选项的概率和置信度 <code>(n * peak - 1) / (n - 1)</code>；score 返回期望级别。</p><ul><li>原始标签概率通常过于自信。每次请求的 <code>temperature</code> 选项在归一化前缩放标签 logits；大于 1 的值使分布更平缓。它不改变答案。</li><li>问题依次运行。一个请求的所有问题中，最后一个问题之前的内容都相同，因此服务器的提示词缓存只计算一次。状态出现两次，因此需要两倍于其大小的上下文。</li><li>小模型可能遵循写在状态中的指令。提示词告诉模型将状态当作数据来判断，但这不构成保证。</li><li>Qwen3.5 等混合模型在没有上下文检查点（context checkpoints）时无法回退部分缓存的提示词。如果每个问题都重新处理整个状态，用 <code>--ctx-checkpoints 32 --checkpoint-min-step 0</code> 启动路由器。</li></ul><p><a id="troubleshooting"></a></p><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><p>检查路由器是否可达：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/models</span></span></code></pre></div><ul><li><strong><code>/llama</code> 中没有模型：</strong> 检查 <code>--models-dir</code> 和目录布局，然后重启路由器。</li><li><strong><code>--no-models-autoload</code> 时模型不在 <code>/model</code> 中：</strong> 先用 <code>/llama</code> 加载它。</li><li><strong>加载失败或内存占用过多：</strong> 降低 <code>-c</code> 或卸载其他模型。</li><li><strong>服务器不在路由器模式：</strong> 不带 <code>--model</code>、<code>-m</code> 或 <code>-hf</code> 启动。</li></ul><p>要移除 <code>llama.cpp</code> 提供商和 <code>/llama</code>，在 <code>pi config</code> 的 Built-in 下禁用 <code>llama.cpp</code>，或在<a href="./settings.html#resources">设置</a>中设置 <code>&quot;extensions&quot;: [&quot;-builtin:llama.cpp&quot;]</code>。</p>`,42)])])}const k=e(o,[["render",n]]);export{g as __pageData,k as default};
